class Shape {
    String describe() { return "I am a shape"; }
}
class Circle extends Shape {
    double radius;
    Circle(double r) { this.radius = r; }
    @Override
    String describe() { return "Circle with radius " + radius; }
}
// Test: new Circle(5.0).describe() → "Circle with radius 5.0"

